const ERROR: f64 = f64::from_bits(0x3d23_6000_0000_000c);

/// `round_line`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: i128, b: i128, d: i128, p: P2, cx: i128, cy: i128, w: i128) -> Option<Sign> {
    let a = rounded_f64(a, 41)?;
    let cx = rounded_f64(cx, 124)?;
    let h_1 = a * cx;
    let b = rounded_f64(b, 41)?;
    let cy = rounded_f64(cy, 124)?;
    let h_2 = b * cy;
    let h_3 = h_1 + h_2;
    let d = rounded_f64(d, 82)?;
    let w = rounded_f64(w, 83)?;
    let h_4 = d * w;
    let h = h_3 - h_4;
    let p_x = exact_f64(p.x);
    let dx_1 = w * p_x;
    let dx = dx_1 - cx;
    let p_y = exact_f64(p.y);
    let dy_1 = w * p_y;
    let dy = dy_1 - cy;
    let rr_1 = dx * dx;
    let rr_2 = dy * dy;
    let rr = rr_1 + rr_2;
    let nn_1 = a * a;
    let nn_2 = b * b;
    let nn = nn_1 + nn_2;
    let s_1 = h * h;
    let s_2 = rr * nn;
    let s = s_1 - s_2;
    let m_x = largest_magnitude([p_x]);
    let m_y = largest_magnitude([p_y]);
    let m_n = largest_magnitude([a, b]);
    let m_d = largest_magnitude([d]);
    let m_c = largest_magnitude([cx, cy]);
    let m_w = largest_magnitude([w]);
    let scale = larger(m_d * m_d * m_w * m_w, m_n * m_d * m_c * m_w);
    let scale = larger(scale, m_n * m_n * m_c * m_c);
    let scale = larger(scale, m_y * m_n * m_n * m_c * m_w);
    let scale = larger(scale, m_y * m_y * m_n * m_n * m_w * m_w);
    let scale = larger(scale, m_x * m_n * m_n * m_c * m_w);
    let scale = larger(scale, m_x * m_x * m_n * m_n * m_w * m_w);
    decide(s, ERROR, scale)
}

/// `round_line`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(a: i128, b: i128, d: i128, p: P2, cx: i128, cy: i128, w: i128) -> Option<I384> {
    let a = i64::try_from(within(a, 41)?).ok()?;
    let cx = within(cx, 124)?;
    let h_1 = I256::product_i128(i128::from(a), cx)?;
    let b = i64::try_from(within(b, 41)?).ok()?;
    let cy = within(cy, 124)?;
    let h_2 = I256::product_i128(i128::from(b), cy)?;
    let h_3 = h_1.checked_add(&h_2)?;
    let d = within(d, 82)?;
    let w = within(w, 83)?;
    let h_4 = I256::product_i128(d, w)?;
    let h = h_3.checked_sub(&h_4)?;
    let p_x = p.x.get();
    let dx_1 = w.checked_mul(i128::from(p_x))?;
    let dx = dx_1.checked_sub(cx)?;
    let p_y = p.y.get();
    let dy_1 = w.checked_mul(i128::from(p_y))?;
    let dy = dy_1.checked_sub(cy)?;
    let rr_1 = I256::product_i128(dx, dx)?;
    let rr_2 = I256::product_i128(dy, dy)?;
    let rr = rr_1.checked_add(&rr_2)?;
    let nn_1 = i128::from(a).checked_mul(i128::from(a))?;
    let nn_2 = i128::from(b).checked_mul(i128::from(b))?;
    let nn = nn_1.checked_add(nn_2)?;
    let s_1 = h.resize::<6>()?.checked_mul(&h.resize::<6>()?)?;
    let s_2 = rr.resize::<6>()?.checked_mul_i128(nn)?;
    let s = s_1.checked_sub(&s_2)?;
    Some(s)
}

/// `round_line`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    reason = "one-letter names are the description's points"
)]
pub fn exact(a: i128, b: i128, d: i128, p: P2, cx: i128, cy: i128, w: i128) -> Option<Sign> {
    value(a, b, d, p, cx, cy, w).map(|v| v.signum())
}
